(function() {
  var DATA = [{"q": "¿Qué es exactamente el Plan que MAXX te presenta?", "a": "<p style=\"margin:0;\">Es un <strong>plan de ahorro individual para tu retiro</strong>, con <strong>aportaciones programadas que tú decides</strong>. Funciona como un <strong>vehículo de inversión a largo plazo</strong>, respaldado por una de las aseguradoras más sólidas a nivel mundial, diseñado para construir <span class=\"g\">el patrimonio que te dé libertad</span> el día de mañana — no depender solo del Seguro Social o de tu empresa.</p>", "cat": "Sobre el plan", "snippet": "Es un plan de ahorro individual para tu retiro, con aportaciones programadas que tú decides. Funciona como un..."}, {"q": "¿A partir de qué edad puedo contratarlo?", "a": "<p style=\"margin:0;\">Desde los <strong class=\"o\">18 años cumplidos</strong>. Y <span class=\"g\">entre más joven empieces, mejor</span>: el tiempo es tu mejor aliado para que tu dinero crezca — cada año que adelantas tu arranque es un año más de rendimiento trabajando a tu favor, y una aportación mensual más pequeña para llegar a la misma meta.</p>", "cat": "Sobre el plan", "snippet": "Desde los 18 años cumplidos. Y entre más joven empieces, mejor: el tiempo es tu mejor aliado para que tu diner..."}, {"q": "¿Hay una edad máxima para contratarlo?", "a": "<p style=\"margin:0;\">No. <strong>No existe edad máxima</strong> para contratar tu plan — <span class=\"g\">nunca es tarde</span> para empezar a construir tu patrimonio.</p>", "cat": "Sobre el plan", "snippet": "No. No existe edad máxima para contratar tu plan — nunca es tarde para empezar a construir tu patrimonio."}, {"q": "¿Cuál es el plazo mínimo y máximo del plan?", "a": "<p style=\"margin:0;\">Tu plazo puede ir de <strong class=\"o\">10 a 25 años</strong>, dependiendo de tu edad y lo que es mejor para TI. <span class=\"g\">Tú decides</span> cuál es el que mejor se ajusta a tu meta de retiro.</p>", "cat": "Sobre el plan", "snippet": "Tu plazo puede ir de 10 a 25 años, dependiendo de tu edad y lo que es mejor para TI. Tú decides cuál es el que..."}, {"q": "¿Puedo elegir el plazo que yo quiera?", "a": "<p style=\"margin:0;\">Sí, dentro del rango de <strong class=\"o\">10 a 25 años</strong>. Una vez que lo pactas al inicio de tu plan, ese plazo <strong>queda fijo</strong> — así que <span class=\"g\">vale la pena pensarlo bien desde el arranque</span>, con calma y con toda la información en la mano.</p>", "cat": "Sobre el plan", "snippet": "Sí, dentro del rango de 10 a 25 años. Una vez que lo pactas al inicio de tu plan, ese plazo queda fijo — así q..."}, {"q": "¿Qué pasa cuando termina mi plazo comprometido?", "a": "<p style=\"margin:0;\">Al llegar al final de tu plazo, <span class=\"g\">tú decides</span> qué sigue: puedes disponer de tu patrimonio como mejor te convenga, o convertirlo en un ingreso recurrente para tu retiro. Es tu dinero, tu esfuerzo — y en ese momento, <span class=\"g\">tú tomas la decisión final sobre tu libertad financiera</span>.</p>", "cat": "Sobre el plan", "snippet": "Al llegar al final de tu plazo, tú decides qué sigue: puedes disponer de tu patrimonio como mejor te convenga,..."}, {"q": "¿Puedo seguir aportando después de que termine mi plazo?", "a": "<p style=\"margin:0;\">Depende de cómo pactaste tu plan desde el inicio: si elegiste el plazo máximo de <strong class=\"o\">25 años</strong>, puedes seguir aportando después de cumplirlo. Si elegiste un plazo menor, para seguir ahorrando necesitarías contratar un nuevo plan. Por eso <span class=\"g\">vale la pena pensar en grande desde el arranque</span>.</p>", "cat": "Sobre el plan", "snippet": "Depende de cómo pactaste tu plan desde el inicio: si elegiste el plazo máximo de 25 años, puedes seguir aporta..."}, {"q": "¿Con quién es el contrato? ¿Qué debo hacer para contratar?", "a": "<p style=\"margin:0;\"><strong>Tu contrato es directo con la aseguradora</strong> — la aseguradora #1 del mundo.<br><br><strong>MAXX no forma parte del contrato</strong>, y nuestra gestión contigo es <strong>100% gratuita</strong> — nunca te cobramos nada por acompañarte.<br><br>El proceso no es una firma tradicional — es más simple, y <strong>protege TUS datos</strong>:<br><br>a) <strong>Agenda TU Cita</strong> (gratuita, sin compromiso). Ahí diseñamos juntos <strong>TU Plan ideal</strong>.<br>b) MAXX te da acceso e instrucciones para entrar <strong>tú mismo</strong>, de forma personal, al portal de la aseguradora — así, MAXX <strong>nunca conoce ni guarda</strong> tus datos bancarios ni información sensible.<br>c) Ahí registras tus propios datos: información personal, <strong>TU aportación, TU plazo, y TU portafolio</strong> elegido, además de tus datos bancarios para la domiciliación.<br>d) La aseguradora recibe tu información, <strong>emite TU póliza</strong>, cobra tu primera aportación, y te entrega tu propia <strong>clave de acceso al portal</strong>.<br>e) Con esa clave, puedes consultar <strong>TU estado de cuenta y rendimientos</strong>, o hacer cualquier trámite, cuando quieras, tú mismo — y <strong>MAXX sigue ahí, siempre</strong>, para acompañarte y ayudarte con lo que necesites.<br><br><a href=\"#cita-desde-faqs\" style=\"color:#185FA5; font-weight:bold;\">Agenda TU Cita aquí →</a></p>", "cat": "Sobre el plan", "snippet": "Tu contrato es directo con la aseguradora — la aseguradora #1 del mundo. MAXX no forma parte del contrato, y n..."}, {"q": "¿Cada cuánto tengo que aportar?", "a": "<p style=\"margin:0;\">Tú eliges: <strong>mensual, trimestral, semestral o anual</strong>. Lo importante es <span class=\"g\">la constancia, no la frecuencia</span> — aunque en la práctica, la mayoría prefiere la <strong>aportación mensual</strong>, porque se domicilia directo a su tarjeta de crédito o débito y se vuelve un hábito automático, con un monto que se siente cómodo y manejable mes a mes, sin pensarlo dos veces.</p>", "cat": "Sobre tus aportaciones", "snippet": "Tú eliges: mensual, trimestral, semestral o anual. Lo importante es la constancia, no la frecuencia — aunque e..."}, {"q": "¿Cómo se cobran mis aportaciones?", "a": "<p style=\"margin:0;\"><strong>Sin ningún costo adicional</strong>, tus aportaciones se cargan directo a tu <strong>tarjeta de crédito</strong> o se domician a tu <strong>cuenta de cheques</strong>. Si prefieres aportar una vez al año, también puedes hacerlo por <strong>transferencia electrónica</strong>. <span class=\"g\">Tú eliges</span> lo que mejor se acomode a tu forma de manejar tu dinero.</p>", "cat": "Sobre tus aportaciones", "snippet": "Sin ningún costo adicional, tus aportaciones se cargan directo a tu tarjeta de crédito o se domician a tu cuen..."}, {"q": "¿Qué pasa si un mes no puedo pagar mi aportación?", "a": "<p style=\"margin:0;\">Depende del momento en el que estés dentro de tu plan. Durante los primeros <strong class=\"o\">18 meses</strong>, tienes <strong>60 días de gracia</strong> a partir de la fecha programada para ponerte al corriente. Después de ese periodo inicial, tu plan puede seguir vigente aunque pauses tus aportaciones — la vida pasa, y tu plan está diseñado para acompañarte sin castigarte por eso.<br><br>Eso sí: <span class=\"g\">mantener la constancia es lo que más te conviene</span>. Cada aportación puntual te acerca a tu meta más rápido, protege tu <strong>Bono de Constancia (o Bono de Fidelidad)</strong> y evita que tengas que postergar tu retiro. <span class=\"g\">Tu compromiso hoy es tu libertad mañana.</span></p>", "cat": "Sobre tus aportaciones", "snippet": "Depende del momento en el que estés dentro de tu plan. Durante los primeros 18 meses, tienes 60 días de gracia..."}, {"q": "¿Puedo aumentar o disminuir el monto de mi aportación más adelante?", "a": "<p style=\"margin:0;\">Sí. Una vez que cumples tu <strong>plazo inicial de 18 meses</strong>, puedes ajustar el monto de tu aportación (hacia arriba o hacia abajo), siempre respetando el <strong>mínimo establecido por la aseguradora</strong>. <span class=\"g\">Tu plan se adapta a las distintas etapas de tu vida — no al revés.</span></p>", "cat": "Sobre tus aportaciones", "snippet": "Sí. Una vez que cumples tu plazo inicial de 18 meses, puedes ajustar el monto de tu aportación (hacia arriba o..."}, {"q": "¿Si disminuyo mi aportación, pierdo algo?", "a": "<p style=\"margin:0;\">Sí, hay un ajuste importante que debes conocer: si <strong>disminuyes</strong> tu aportación comprometida, tu <strong>Bono de Constancia se recalcula a la baja</strong>, según el nuevo monto. En cambio, si la <strong>aumentas</strong>, tu bono ya ganado <strong>no cambia</strong>. Por eso, <span class=\"g\">antes de bajar tu aportación, vale la pena pensarlo bien</span> — o platicarlo con tu asesor para ver otras opciones, como el Periodo de Descanso.</p>", "cat": "Sobre tus aportaciones", "snippet": "Sí, hay un ajuste importante que debes conocer: si disminuyes tu aportación comprometida, tu Bono de Constanci..."}, {"q": "¿Puedo aportar más de lo que me comprometí, si quiero ahorrar extra?", "a": "<p style=\"margin:0;\">Claro. En cualquier momento puedes hacer <strong>aportaciones adicionales</strong>, más allá de lo que pactaste. Es una forma excelente de <span class=\"g\">acelerar tu meta</span> cuando te llega un ingreso extra — un bono, un aguinaldo, una buena quincena — y <span class=\"g\">convertirlo en más libertad para tu futuro</span>, en lugar de que se diluya en gastos del día a día.</p>", "cat": "Sobre tus aportaciones", "snippet": "Claro. En cualquier momento puedes hacer aportaciones adicionales, más allá de lo que pactaste. Es una forma e..."}, {"q": "¿Cuál es la aportación mínima para contratar un plan?", "a": "<p style=\"margin:0;\">Empezar es <span class=\"g\">más accesible de lo que crees</span>: con solo <strong class=\"o\">$3,000 pesos al mes</strong> puedes contratar un plan de <strong>10 a 14 años</strong>, o con <strong class=\"o\">$2,000 pesos al mes</strong> si eliges un plazo de <strong>15 años en adelante</strong>. <span class=\"g\">No necesitas una fortuna para empezar — necesitas decidirte hoy.</span> Entre más joven empieces, con menos puedes construir más (recuerda: el tiempo es tu mejor aliado).<br><br><em>Nota: si tienes 59 años o más, el plazo máximo que puedes contratar es de 10 años.</em></p>", "cat": "Sobre tus aportaciones", "snippet": "Empezar es más accesible de lo que crees: con solo $3,000 pesos al mes puedes contratar un plan de 10 a 14 año..."}, {"q": "¿Qué es el \"Periodo de Descanso\" y cómo lo uso?", "a": "<p style=\"margin:0;\">Es tu <span class=\"g\">derecho a pausar sin culpa</span>. Una vez que cumples tu <strong>plazo inicial de 18 meses</strong>, tienes derecho a <strong>UN periodo de hasta 12 meses consecutivos</strong> para suspender tus aportaciones — sin costos adicionales y sin que tu Bono de Constancia se vea afectado. Ideal para cuando la vida te presenta un imprevisto, o una oportunidad que requiere tu dinero en otro lado.<br><br>Solo necesitas avisar por escrito con al menos <strong>5 días hábiles de anticipación</strong> a tu siguiente fecha de aportación. Y si decides retomar tus pagos antes de que se cumplan los 12 meses, pierdes los meses restantes de ese derecho — así que úsalo con calma, pero úsalo cuando lo necesites.<br><br><strong>Importante:</strong> después del plazo inicial, tu póliza puede seguir vigente aunque dejes de aportar sin declarar tu Periodo de Descanso — pero esa pausa \"informal\" no está protegida de la misma forma, y puede poner en riesgo tu Bono de Constancia si te desvías de tu esquema de pagos. Por eso, si vas a pausar, <span class=\"g\">lo más inteligente es hacerlo formalmente</span>, avisando y usando tu Periodo de Descanso.</p>", "cat": "Sobre tus aportaciones", "snippet": "Es tu derecho a pausar sin culpa. Una vez que cumples tu plazo inicial de 18 meses, tienes derecho a UN period..."}, {"q": "¿Quién cobra mis aportaciones?", "a": "<p style=\"margin:0;\"><strong>La aseguradora cobra directo</strong> — vía domiciliación a tu tarjeta o cuenta bancaria, tal como <strong>tú mismo</strong> la registraste en su portal.<br><br><strong>MAXX nunca toca TU dinero.</strong> No lo recibimos, no lo administramos, y <strong>no tenemos acceso a tus datos bancarios</strong> — esa relación es exclusivamente entre <strong>TÚ</strong> y la aseguradora.<br><br>Esto no es casualidad — la <strong>Ley de Instituciones de Seguros y de Fianzas (Art. 99)</strong> es clara en cómo debe manejarse el cobro de primas en México, precisamente para proteger al cliente. En MAXX seguimos ese espíritu al pie de la letra: <strong>TUS aportaciones van directo a una institución regulada</strong>, sin pasar por ningún intermediario.</p>", "cat": "Sobre tus aportaciones", "snippet": "La aseguradora cobra directo — vía domiciliación a tu tarjeta o cuenta bancaria, tal como tú mismo la registra..."}, {"q": "¿Qué es el Bono de Fidelidad?", "a": "<p style=\"margin:0;\">Es el <span class=\"g\">premio a tu disciplina</span>. Por tu compromiso y constancia en el ahorro, puedes recibir un bono de hasta el <strong class=\"o\">100%</strong> sobre tus aportaciones comprometidas del primer año de tu plan. Es tu recompensa por hacer lo que la mayoría de las personas nunca hace: <span class=\"g\">empezar y sostenerlo</span>.</p>", "cat": "Sobre el Bono de Fidelidad", "snippet": "Es el premio a tu disciplina. Por tu compromiso y constancia en el ahorro, puedes recibir un bono de hasta el..."}, {"q": "¿Cómo sé qué porcentaje de bono me corresponde a mí?", "a": "<p style=\"margin:0;\">Depende de dos cosas: <strong>tu plazo comprometido</strong> y <strong>tu aportación anual</strong>. Entre más largo tu plazo y más alta tu aportación, mayor tu bono — hasta llegar al <strong class=\"o\">100%</strong> con un plazo de 20 a 25 años y una aportación anual de $90,000 pesos o más.<br><br><a href=\"#section05\" style=\"color:#185FA5; font-weight:bold;\">Consulta la tabla completa aquí →</a> y descubre exactamente qué porcentaje te corresponde a TI.</p>", "cat": "Sobre el Bono de Fidelidad", "snippet": "Depende de dos cosas: tu plazo comprometido y tu aportación anual. Entre más largo tu plazo y más alta tu apor..."}, {"q": "¿El bono es automático o tengo que hacer algo para ganarlo?", "a": "<p style=\"margin:0;\">Tienes que <span class=\"g\">ganártelo con constancia</span> — no llega solo. El bono se va acumulando conforme pagas tus aportaciones del primer año, mes a mes, no de golpe. Y para poder disponer de él al final de tu plazo contratado, necesitas dos cosas: haber mantenido tu calendario de pagos como lo pactaste, y que el saldo promedio de tu plan sea de al menos el <strong class=\"o\">50%</strong> de lo comprometido durante todo el plazo.<br><br><span class=\"g\">Es tuyo, pero se gana con constancia.</span></p>", "cat": "Sobre el Bono de Fidelidad", "snippet": "Tienes que ganártelo con constancia — no llega solo. El bono se va acumulando conforme pagas tus aportaciones..."}, {"q": "¿Puedo perder el Bono de Fidelidad?", "a": "<p style=\"margin:0;\"><strong>Puede verse afectado</strong> si te desvías mucho de tu plan — por ejemplo, si <strong>dejas de pagar tus aportaciones sin declarar formalmente tu Periodo de Descanso</strong>, o si tu <strong>saldo promedio cae por debajo del 50%</strong> de lo comprometido. Por eso la constancia no es solo una recomendación: <span class=\"g\">es lo que protege tu bono</span>. La buena noticia: <span class=\"g\">mientras sigas tu plan como lo pactaste, tu bono está seguro y sigue creciendo contigo</span>.</p>", "cat": "Sobre el Bono de Fidelidad", "snippet": "Puede verse afectado si te desvías mucho de tu plan — por ejemplo, si dejas de pagar tus aportaciones sin decl..."}, {"q": "¿El bono también genera rendimiento, o se queda fijo?", "a": "<p style=\"margin:0;\"><span class=\"g\">No se queda quieto — también invierte y crece.</span> Tu Bono de Constancia genera rendimientos a una tasa de <strong class=\"o\">inflación + 5% anual</strong>, con un tope del <strong>9% anual</strong>. Es decir, mientras tu plan sigue corriendo, tu bono también trabaja para ti, sumando valor por su cuenta hasta el día en que lo recibas.</p>", "cat": "Sobre el Bono de Fidelidad", "snippet": "No se queda quieto — también invierte y crece. Tu Bono de Constancia genera rendimientos a una tasa de inflaci..."}, {"q": "Si bajo mi aportación, ¿qué pasa con mi bono ya ganado?", "a": "<p style=\"margin:0;\">Tu bono se <strong>recalcula a la baja</strong>, ajustándose al nuevo nivel de aportación según la tabla de porcentajes. En cambio, si en algún momento <strong>aumentas</strong> tu aportación, tu bono <strong>no cambia</strong> — se queda en el nivel que ya tenías. Por eso, antes de bajar tu aportación, vale la pena pensarlo dos veces, o explorar primero tu <span class=\"g\">Periodo de Descanso</span>, que sí protege tu bono por completo.</p>", "cat": "Sobre el Bono de Fidelidad", "snippet": "Tu bono se recalcula a la baja, ajustándose al nuevo nivel de aportación según la tabla de porcentajes. En cam..."}, {"q": "¿Puedo sacar mi dinero antes de que termine el plazo?", "a": "<p style=\"margin:0;\">Sí. Tu plan está pensado para <span class=\"g\">acompañarte, no para atarte</span>.<br><br>A partir del <strong class=\"o\">mes 19</strong>, puedes hacer <strong>retiros parciales</strong> sobre tu saldo comprometido cuando lo necesites. <span class=\"g\">Tu dinero sigue siendo tuyo</span>, con acceso cuando la vida lo requiera.</p>", "cat": "Tu dinero: acceso y liquidez", "snippet": "Sí. Tu plan está pensado para acompañarte, no para atarte. A partir del mes 19, puedes hacer retiros parciales..."}, {"q": "¿Tiene algún costo retirar antes de tiempo?", "a": "<p style=\"margin:0;\">Sí, y hay dos cosas que debes tener claras.<br><br>Primero, un <strong>cargo administrativo del 1%</strong> sobre el monto que retires antes de cumplir tu plazo comprometido — una vez que cumples tu plazo, tu saldo total queda disponible para retiro sin ningún cargo.<br><br>Segundo, y muy importante: retirar antes de tiempo también puede tener implicaciones de <strong>ISR</strong>. Los beneficios fiscales de tu plan (deducción y diferimiento de impuestos) están ligados a que mantengas tu dinero invertido el tiempo que marca la Ley — si retiras antes de cumplir esos requisitos de permanencia, es probable que ese retiro sí genere impuesto. Por eso, <span class=\"g\">entre más aguantes tu plan hasta la meta, más completo y más libre de impuestos llega tu patrimonio a tus manos</span>.<br><br><em>Te recomendamos que antes de hacer un retiro anticipado, te asesores en cuanto al impacto fiscal que pudiese corresponder.</em></p>", "cat": "Tu dinero: acceso y liquidez", "snippet": "Sí, y hay dos cosas que debes tener claras. Primero, un cargo administrativo del 1% sobre el monto que retires..."}, {"q": "¿Puedo pedir un préstamo sobre mi ahorro sin cancelar mi plan?", "a": "<p style=\"margin:0;\">Sí.<br><br>A partir del <strong class=\"o\">mes 19</strong>, puedes obtener un <strong>préstamo sobre tu propio fondo</strong>, a una tasa preferencial, sin necesidad de tocar ni cancelar tu plan.<br><br>Tu dinero <span class=\"g\">sigue invertido y generando rendimiento</span> mientras usas el préstamo — lo mejor de los dos mundos: liquidez cuando la necesitas, y tu patrimonio que sigue creciendo.<br><br><em>(Aplican restricciones y montos mínimos/máximos que la aseguradora actualiza, y que en su momento MAXX te podrá informar).</em></p>", "cat": "Tu dinero: acceso y liquidez", "snippet": "Sí. A partir del mes 19, puedes obtener un préstamo sobre tu propio fondo, a una tasa preferencial, sin necesi..."}, {"q": "¿Qué pasa con mi dinero si cancelo mi plan?", "a": "<p style=\"margin:0;\">Este plan está pensado para acompañarte muchos años — y <strong>la gran mayoría de nuestros clientes nunca llega a cancelar</strong>. Aun así, aquí está todo con claridad, según en qué momento de tu plan estés:<br><br><strong>Durante tus primeros 18 meses</strong>, es la etapa donde más importa tu constancia. Estas primeras aportaciones son las que construyen la base de tu plan — y completarlas es lo que te abre la puerta a toda la flexibilidad que viene después. Si por alguna razón no logras completarlas, el riesgo real es <strong>perder lo que hayas aportado</strong> hasta ese momento — por eso, en MAXX te acompañamos de cerca desde el inicio, para ayudarte a cumplir esta primera etapa sin contratiempos. Las reglas específicas de este periodo las platicamos a detalle en tu cita, con total transparencia.<br><br><strong>A partir del mes 19</strong>, ya cumpliste tu primera etapa, y con eso ganas más flexibilidad: puedes pausar tus aportaciones sin costo (<strong>Periodo de Descanso</strong>) o hacer un <strong>retiro parcial</strong> — ambos te dan liquidez sin tener que cancelar tu plan completo.<br><br><strong>Y si aun así decides cancelar a partir del mes 19:</strong> tu dinero <strong>sigue siendo tuyo</strong> — se te entrega tu saldo acumulado, con dos ajustes: un cargo por retiro del 1%, y renuncias a tu Bono de Fidelidad (el premio que solo se gana cumpliendo el plazo completo).<br><br><em>(Nota extra: para que el rendimiento generado quede libre de impuestos, también necesitas cumplir 60 años y 5 años de vigencia — lo revisamos contigo en tu cita, según tu caso.)</em></p>", "cat": "Tu dinero: acceso y liquidez", "snippet": "Este plan está pensado para acompañarte muchos años — y la gran mayoría de nuestros clientes nunca llega a can..."}, {"q": "¿En qué se invierte mi dinero?", "a": "<p style=\"margin:0;\">Tu dinero se invierte en <strong>Alternativas de Inversión</strong> que tú eliges, con distintos perfiles de riesgo y monedas — desde opciones conservadoras hasta otras más dinámicas, incluyendo estrategias ligadas a mercados como el <strong>S&amp;P 500</strong>.<br><br><a href=\"#section09\" style=\"color:#185FA5; font-weight:bold;\">Conoce a detalle tus opciones aquí →</a></p>", "cat": "Tu dinero: acceso y liquidez", "snippet": "Tu dinero se invierte en Alternativas de Inversión que tú eliges, con distintos perfiles de riesgo y monedas —..."}, {"q": "¿Puedo elegir o cambiar en dónde se invierte mi dinero?", "a": "<p style=\"margin:0;\">Sí, y con mucha libertad.<br><br>Puedes asignar tu inversión a cualquiera de las <strong class=\"o\">19 Alternativas de Inversión</strong> disponibles, o mezclarlas como tú prefieras.<br><br>No es una decisión de una sola vez: <span class=\"g\">mes a mes puedes redistribuir</span> la composición de tu inversión conforme cambien tus necesidades o tu visión del mercado. <span class=\"g\">Tú tienes el control, siempre.</span><br><br><a href=\"#section09\" style=\"color:#185FA5; font-weight:bold;\">Conoce las 19 alternativas disponibles →</a></p>", "cat": "Tu dinero: acceso y liquidez", "snippet": "Sí, y con mucha libertad. Puedes asignar tu inversión a cualquiera de las 19 Alternativas de Inversión disponi..."}, {"q": "¿Qué pasa con mis rendimientos, dónde los veo reflejados?", "a": "<p style=\"margin:0;\">Tu rendimiento se refleja mes a mes en tu <strong>estado de cuenta</strong>, donde puedes ver el valor actualizado de tus <strong>Unidades de Inversión</strong> en cada Alternativa que hayas elegido — se revalúan <strong>diariamente</strong> con base en el valor de mercado real. <span class=\"g\">Total transparencia: siempre sabes exactamente cuánto vale tu patrimonio, y cómo está creciendo.</span></p>", "cat": "Tu dinero: acceso y liquidez", "snippet": "Tu rendimiento se refleja mes a mes en tu estado de cuenta, donde puedes ver el valor actualizado de tus Unida..."}, {"q": "¿Es cierto que puedo deducir de impuestos lo que ahorro aquí?", "a": "<p style=\"margin:0;\">Sí, y es uno de los beneficios más poderosos de tu plan.<br><br>El gobierno mexicano incentiva el ahorro para el retiro con <strong>tres beneficios fiscales distintos</strong>:<br><br>a) puedes <strong>deducir</strong> lo que aportas,<br>b) <strong>diferir</strong> el impuesto sobre tus rendimientos, y<br>c) en algunos casos <strong>retirar sin pagar impuestos</strong> al final.<br><br><span class=\"g\">La mayoría no lo sabe. Los que sí lo saben, lo aprovechan.</span><br><br>Revisa las preguntas <em>\"¿Qué es la deducibilidad?\"</em>, <em>\"¿Qué es el diferimiento?\"</em> y <em>\"¿Qué es la exención de impuestos?\"</em> para entender cada uno a detalle.</p>", "cat": "Impuestos y beneficios fiscales", "snippet": "Sí, y es uno de los beneficios más poderosos de tu plan. El gobierno mexicano incentiva el ahorro para el reti..."}, {"q": "¿Qué es la deducibilidad y cómo me beneficia?", "a": "<p style=\"margin:0;\">Es simple: <strong>cada aportación que haces baja lo que declaras al SAT</strong>. Entre menos base gravable tengas, <span class=\"g\">menos impuesto pagas</span> — así de directo.<br><br>Un ejemplo real, con un ingreso anual de <strong>$1,000,000 de pesos</strong> y una tasa de impuesto del <strong>32%</strong>:<br><br><strong>Sin deducir:</strong><br>Ingreso: $1,000,000<br>Deducción: $0<br>Base gravable: $1,000,000<br>Impuesto (32%): <strong class=\"o\">$320,000</strong><br><br><strong>Deduciendo $100,000:</strong><br>Ingreso: $1,000,000<br>− Deducción: $100,000<br>= Base gravable: $900,000<br>Impuesto (32%): <strong class=\"o\">$288,000</strong><br><br><span class=\"g\">Tu ahorro: $32,000 pesos</span> — dinero que <span class=\"g\">te quedas tú, no el SAT</span>. Es dinero que puedes dejar de pagar en impuestos, para invertirlo en tu futuro en su lugar.</p>", "cat": "Impuestos y beneficios fiscales", "snippet": "Es simple: cada aportación que haces baja lo que declaras al SAT. Entre menos base gravable tengas, menos impu..."}, {"q": "¿Qué es el diferimiento de impuestos?", "a": "<p style=\"margin:0;\">Es <strong>posponer el pago de impuestos sobre tus rendimientos</strong>, hasta el momento en que retires tu dinero — en vez de pagarlos cada año, como pasa en otros instrumentos de inversión.<br><br><strong>Aplica desde el primer día de tu plan</strong>, sin importar tu edad ni cuánto tiempo llevas invirtiendo.<br><br>Mientras más tiempo dejas crecer tu dinero, <span class=\"g\">más grande es el beneficio</span>. Usando supuestos conservadores (4% de rendimiento real anual, 30% de impuesto), esto es lo que ganas de más, comparado con un instrumento que sí paga impuestos cada año:<br><br>a) A <strong>10 años</strong>: tienes ~12% más dinero.<br>b) A <strong>15 años</strong>: tienes ~19% más dinero.<br>c) A <strong>20 años</strong>: tienes ~26% más dinero.<br>d) A <strong>25 años</strong>: tienes <strong class=\"o\">hasta 31% más dinero</strong>.<br><br><em>Los valores son estimaciones ilustrativas y pueden variar según tu perfil de inversión, plazo real y condiciones de mercado — te recomendamos confirmar tu caso específico con tu asesor.</em><br><br>Mientras <span class=\"g\">más tiempo lo dejes crecer, mayor es el beneficio</span> — pero <span class=\"g\">lo tienes desde el primer momento</span>.</p>", "cat": "Impuestos y beneficios fiscales", "snippet": "Es posponer el pago de impuestos sobre tus rendimientos, hasta el momento en que retires tu dinero — en vez de..."}, {"q": "¿Qué es la exención de impuestos y cuándo aplica?", "a": "<p style=\"margin:0;\">Es el mayor de los beneficios fiscales: significa que, si cumples los requisitos, <strong>no pagas impuesto al retirar tu dinero</strong> — ni un peso.<br><br>Depende de qué artículo ampara tu plan:<br><br>• <strong>Artículo 93</strong>: tu retiro queda <strong class=\"o\">100% exento</strong> si tienes 60 años o más y llevas al menos 5 años con tu plan.<br>• <strong>Artículo 151</strong>: al cumplir 65 años, puedes retirar hasta 15 UMAs por año sin pagar impuesto.<br>• <strong>Artículo 185</strong>: no incluye este beneficio de exención — su fortaleza está en la deducibilidad y el diferimiento, que ya viste en las preguntas anteriores.<br><br>Un ejemplo real de lo que esto significa: con un ingreso de $1,000,000 de pesos y $500,000 de ese ingreso exento, tu impuesto (a una tasa del 32%) baja de $320,000 a $160,000. <span class=\"g\">Eso son $160,000 pesos que te quedas tú, no el SAT.</span><br><br><span class=\"g\">Cumplir los requisitos de permanencia no es un trámite — es la diferencia entre compartir tu dinero con el SAT o quedártelo todo.</span></p>", "cat": "Impuestos y beneficios fiscales", "snippet": "Es el mayor de los beneficios fiscales: significa que, si cumples los requisitos, no pagas impuesto al retirar..."}, {"q": "¿Cuánto puedo deducir al año?", "a": "<p style=\"margin:0;\">Depende de qué artículo uses, pero puedes combinarlos para maximizar tu deducción:<br><br>• <strong>Artículo 151</strong>: hasta el 10% de tu ingreso anual, con un tope de 5 UMAs (aproximadamente $198,032 pesos al año).<br>• <strong>Artículo 185</strong>: hasta $152,000 pesos adicionales.<br><br><span class=\"g\">Combinando ambos, el SAT te permite deducir hasta</span> <strong class=\"o\">$203,400 pesos al año</strong> — si ahorras correctamente. La mayoría no lo sabe. <span class=\"g\">Los que sí lo saben, lo aprovechan.</span><br><br><em>(Las Deducciones Personales totales, sumando todo lo deducible en tu declaración anual, no pueden exceder el 15% de tu ingreso o el equivalente a 5 UMAs anuales — se toma la cifra que resulte menor.)</em></p>", "cat": "Impuestos y beneficios fiscales", "snippet": "Depende de qué artículo uses, pero puedes combinarlos para maximizar tu deducción: • Artículo 151: hasta el 10..."}, {"q": "¿Cuándo puedo retirar mi dinero sin pagar impuestos?", "a": "<p style=\"margin:0;\">Se conecta directo con lo que viste en <em>\"¿Qué es la exención de impuestos?\"</em> — depende del artículo que ampare tu plan:<br><br>• <strong>Artículo 93</strong>: sin pagar impuesto, si tienes 60 años o más y llevas al menos 5 años con tu plan.<br>• <strong>Artículo 151</strong>: sin pagar impuesto (hasta 15 UMAs anuales), a partir de los 65 años.<br>• <strong>Artículo 185</strong>: siempre se grava — este artículo no ofrece exención, pero sí deducibilidad y diferimiento.<br><br>Retirar antes de cumplir estos requisitos no cancela tu plan, pero sí significa que ese retiro estará sujeto a impuesto. Por eso, <span class=\"g\">entre más aguantes hasta cumplir tus requisitos de permanencia, más completo y más libre de impuestos llega tu dinero a tus manos</span>.</p>", "cat": "Impuestos y beneficios fiscales", "snippet": "Se conecta directo con lo que viste en \"¿Qué es la exención de impuestos?\" — depende del artículo que ampare t..."}, {"q": "¿Necesito un contador para aprovechar estos beneficios?", "a": "<p style=\"margin:0;\">No es obligatorio, pero <span class=\"g\">sí se recomienda</span> — sobre todo si quieres optimizar al máximo tu deducción o tienes una situación fiscal particular (varios ingresos, otras deducciones, etc.).<br><br>Tu plan está diseñado para que los beneficios apliquen de forma automática, pero un contador puede ayudarte a sacarle el máximo provecho a tu declaración anual.<br><br>Nosotros te acompañamos en todo el proceso — y para lo estrictamente fiscal, siempre es buena idea tener a tu contador de confianza.</p>", "cat": "Impuestos y beneficios fiscales", "snippet": "No es obligatorio, pero sí se recomienda — sobre todo si quieres optimizar al máximo tu deducción o tienes una..."}, {"q": "¿Cómo actualizo mis datos personales?", "a": "<p style=\"margin:0;\">Puedes solicitarlo en cualquier momento de la vigencia de tu plan. Se hace por correo electrónico, con tu solicitud de movimientos e identificación oficial vigente — <span class=\"g\">la aseguradora y MAXX te compartirán las direcciones de correo para la gestión de tu trámite.</span> Te confirman por correo cuando el cambio ya esté hecho.</p>", "cat": "Trámites y operaciones de tu plan", "snippet": "Puedes solicitarlo en cualquier momento de la vigencia de tu plan. Se hace por correo electrónico, con tu soli..."}, {"q": "¿Cómo cambio mi correo o teléfono de contacto?", "a": "<p style=\"margin:0;\">Puedes hacerlo tú mismo, en cualquier momento, directo desde tu <strong>Portal de Clientes</strong>, en la sección de configuración. Es el trámite más rápido de todos — no necesitas enviar documentos ni esperar confirmación por correo.<br><br><em>Encuentras el enlace exacto en tu contrato/póliza — y MAXX te acompaña en todo momento durante el trámite.</em></p>", "cat": "Trámites y operaciones de tu plan", "snippet": "Puedes hacerlo tú mismo, en cualquier momento, directo desde tu Portal de Clientes, en la sección de configura..."}, {"q": "¿Cómo cambio a mis beneficiarios?", "a": "<p style=\"margin:0;\">Se hace con documentación física en oficina: llevas tu solicitud de movimientos a la póliza e identificación oficial vigente. Puedes solicitarlo en cualquier momento de la vigencia de tu plan.<br><br><em>Encuentras el detalle exacto en tu contrato/póliza — y MAXX te acompaña en todo momento durante el trámite.</em></p>", "cat": "Trámites y operaciones de tu plan", "snippet": "Se hace con documentación física en oficina: llevas tu solicitud de movimientos a la póliza e identificación o..."}, {"q": "¿Cómo cambio mi tarjeta o cuenta de cobro?", "a": "<p style=\"margin:0;\">Se hace por correo electrónico, en cualquier momento de la vigencia de tu plan. Necesitas: tu solicitud de movimientos firmada, identificación oficial vigente, y copia de tu nuevo conducto de cobro (tarjeta, cuenta de cheques, ahorro o nómina, a tu nombre).<br><br><em>Encuentras las direcciones de correo exactas en tu contrato/póliza — y MAXX te acompaña en todo momento durante el trámite.</em></p>", "cat": "Trámites y operaciones de tu plan", "snippet": "Se hace por correo electrónico, en cualquier momento de la vigencia de tu plan. Necesitas: tu solicitud de mov..."}, {"q": "¿Puedo cambiar la fecha en que se cobra mi aportación?", "a": "<p style=\"margin:0;\">Sí, en cualquier momento de la vigencia de tu plan. Lo haces tú mismo desde tu <strong>Portal de Clientes</strong>, en la sección de trámites y cambio de fecha de pago.<br><br><em>Encuentras el enlace exacto en tu contrato/póliza — y MAXX te acompaña en todo momento durante el trámite.</em></p>", "cat": "Trámites y operaciones de tu plan", "snippet": "Sí, en cualquier momento de la vigencia de tu plan. Lo haces tú mismo desde tu Portal de Clientes, en la secci..."}, {"q": "¿Cómo solicito un aumento o disminución de mi aportación?", "a": "<p style=\"margin:0;\">Se hace por correo electrónico, a partir del <strong class=\"o\">mes 19</strong> de tu plan. Necesitas estar al corriente con tus aportaciones para poder solicitarlo.<br><br>Recuerda: si <strong>disminuyes</strong>, tu Bono de Constancia se ajusta a la baja. Si <strong>aumentas</strong>, tu bono no cambia.<br><br><em>Encuentras las direcciones de correo exactas en tu contrato/póliza — y MAXX te acompaña en todo momento durante el trámite.</em></p>", "cat": "Trámites y operaciones de tu plan", "snippet": "Se hace por correo electrónico, a partir del mes 19 de tu plan. Necesitas estar al corriente con tus aportacio..."}, {"q": "¿Puedo mover mi dinero entre alternativas de inversión ya contratadas?", "a": "<p style=\"margin:0;\">Sí, de dos formas:<br><br>• <strong>Traspaso de saldo</strong> entre alternativas: lo haces tú mismo desde tu Portal de Clientes, a partir del mes 19 (o antes, si tienes aportaciones adelantadas que superen los primeros 18 meses). Monto mínimo: $10,000 pesos.<br>• <strong>Redistribución de aportaciones futuras</strong> entre portafolios: se solicita por correo electrónico, en cualquier momento, respetando los montos mínimos de cada alternativa.<br><br><em>Encuentras el enlace y las direcciones de correo exactas en tu contrato/póliza — y MAXX te acompaña en todo momento durante el trámite.</em></p>", "cat": "Trámites y operaciones de tu plan", "snippet": "Sí, de dos formas: • Traspaso de saldo entre alternativas: lo haces tú mismo desde tu Portal de Clientes, a pa..."}, {"q": "¿Cómo solicito mi Periodo de Descanso formalmente?", "a": "<p style=\"margin:0;\">Se solicita por correo electrónico, a partir del mes 19. Necesitas estar al corriente con tus aportaciones, y avisar con al menos <strong>5 días hábiles de anticipación</strong> a tu siguiente fecha de cobro.<br><br>Recuerda: hacerlo de forma <span class=\"g\">formal</span> (y no solo dejar de pagar) es lo que protege tu Bono de Constancia.<br><br><em>Encuentras las direcciones de correo exactas en tu contrato/póliza — y MAXX te acompaña en todo momento durante el trámite.</em></p>", "cat": "Trámites y operaciones de tu plan", "snippet": "Se solicita por correo electrónico, a partir del mes 19. Necesitas estar al corriente con tus aportaciones, y..."}, {"q": "¿Cómo solicito un retiro de mi saldo comprometido?", "a": "<p style=\"margin:0;\">Lo haces tú mismo desde tu <strong>Portal de Clientes</strong>, a partir del mes 19 (o antes, si tienes aportaciones adelantadas que superen los primeros 18 meses). Monto mínimo de retiro: $10,000 pesos.<br><br><em>Encuentras el enlace exacto en tu contrato/póliza — y MAXX te acompaña en todo momento durante el trámite.</em></p>", "cat": "Trámites y operaciones de tu plan", "snippet": "Lo haces tú mismo desde tu Portal de Clientes, a partir del mes 19 (o antes, si tienes aportaciones adelantada..."}, {"q": "¿Cómo solicito un préstamo sobre mi plan?", "a": "<p style=\"margin:0;\">Se solicita por correo electrónico, a partir del mes 19. Necesitas: solicitud de movimientos, identificación oficial, y un estado de cuenta con tu CLABE interbancaria (con máximo 3 meses de antigüedad) para recibir el depósito. Si tu préstamo es aceptado, firmas un contrato antes de recibir el dinero.<br><br><em>Encuentras las direcciones de correo exactas en tu contrato/póliza — y MAXX te acompaña en todo momento durante el trámite.</em></p>", "cat": "Trámites y operaciones de tu plan", "snippet": "Se solicita por correo electrónico, a partir del mes 19. Necesitas: solicitud de movimientos, identificación o..."}, {"q": "¿Qué pasa si necesito pausar mi domiciliación (no mi Periodo de Descanso)?", "a": "<p style=\"margin:0;\">Puedes suspender tu domiciliación en cualquier momento de la vigencia de tu plan, solicitándolo por correo electrónico.<br><br><strong>Ojo:</strong> esto es distinto a tu Periodo de Descanso formal. Si suspendes tu domiciliación, <strong class=\"o\">debes reactivarla antes de 60 días naturales</strong> — de lo contrario, corres el riesgo de que tu póliza se cancele o de perder tu Bono de Constancia, según sea el caso.<br><br><em>Encuentras las direcciones de correo exactas en tu contrato/póliza — y MAXX te acompaña en todo momento durante el trámite.</em></p>", "cat": "Trámites y operaciones de tu plan", "snippet": "Puedes suspender tu domiciliación en cualquier momento de la vigencia de tu plan, solicitándolo por correo ele..."}, {"q": "¿Cuánto tiempo tardan estos trámites?", "a": "<p style=\"margin:0;\">Varía según el trámite: algunos son <strong>inmediatos</strong> porque los haces tú mismo desde tu Portal de Clientes (como cambiar tu correo o tu fecha de cobro), y otros requieren revisión por correo electrónico, que suele confirmarse en pocos días hábiles una vez que envías tu documentación completa.<br><br><span class=\"g\">MAXX te acompaña en cada paso</span>, para que ningún trámite se quede atorado por falta de seguimiento.</p>", "cat": "Trámites y operaciones de tu plan", "snippet": "Varía según el trámite: algunos son inmediatos porque los haces tú mismo desde tu Portal de Clientes (como cam..."}, {"q": "¿Qué cargos tiene el plan? (¿tiene algún costo oculto?)", "a": "<p style=\"margin:0;\"><span class=\"g\">Cero costos ocultos</span> — aquí está todo, con transparencia total. Tu plan tiene tres cargos mientras esté vigente:<br><br>• <strong>Cargo Administrativo</strong>: 0.9% trimestral, sobre tu Saldo Inicial y tu Bono de Constancia.<br>• <strong>Cargo de Gestión de Inversión</strong>: 0.1% mensual, sobre tu Saldo Total.<br>• <strong>Cargo Fijo</strong>: 15 UDIS mensuales, a partir del mes 19.<br><br>Entre más largo tu plazo, más eficiente (más barata) es tu tasa de costo por año:<br><br><table style=\"width:100%; border-collapse:collapse; margin:10px 0; font-size:14px;\"><tr style=\"background:#185FA5; color:#fff;\"><th style=\"padding:6px; text-align:left;\">Plazo</th><th style=\"padding:6px; text-align:left;\">Costo Anual Promedio</th></tr><tr><td style=\"padding:6px; border-bottom:1px solid #ddd;\">1.5 años</td><td style=\"padding:6px; border-bottom:1px solid #ddd;\">4.80%</td></tr><tr><td style=\"padding:6px; border-bottom:1px solid #ddd;\">5 años</td><td style=\"padding:6px; border-bottom:1px solid #ddd;\">2.30%</td></tr><tr><td style=\"padding:6px; border-bottom:1px solid #ddd;\">10 años</td><td style=\"padding:6px; border-bottom:1px solid #ddd;\">1.70%</td></tr><tr><td style=\"padding:6px; border-bottom:1px solid #ddd;\">15 años</td><td style=\"padding:6px; border-bottom:1px solid #ddd;\">1.60%</td></tr><tr><td style=\"padding:6px; border-bottom:1px solid #ddd;\">20 años</td><td style=\"padding:6px; border-bottom:1px solid #ddd;\">1.50%</td></tr><tr><td style=\"padding:6px;\"><strong>25 años</strong></td><td style=\"padding:6px;\"><strong class=\"o\">1.40%</strong></td></tr></table>Pero lo más importante no es el costo — <span class=\"g\">es lo que ese costo te ayuda a construir</span>. Con una aportación de $2,000 pesos al mes:<br><br><table style=\"width:100%; border-collapse:collapse; margin:10px 0; font-size:13px;\"><tr style=\"background:#185FA5; color:#fff;\"><th style=\"padding:6px; text-align:left;\">Plazo</th><th style=\"padding:6px; text-align:left;\">Total aportado</th><th style=\"padding:6px; text-align:left;\">Costo estimado*</th><th style=\"padding:6px; text-align:left;\">Patrimonio proyectado**</th></tr><tr><td style=\"padding:6px; border-bottom:1px solid #ddd;\">10 años</td><td style=\"padding:6px; border-bottom:1px solid #ddd;\">$240,000</td><td style=\"padding:6px; border-bottom:1px solid #ddd;\">~$20,400</td><td style=\"padding:6px; border-bottom:1px solid #ddd;\">~$409,690</td></tr><tr><td style=\"padding:6px; border-bottom:1px solid #ddd;\">15 años</td><td style=\"padding:6px; border-bottom:1px solid #ddd;\">$360,000</td><td style=\"padding:6px; border-bottom:1px solid #ddd;\">~$43,200</td><td style=\"padding:6px; border-bottom:1px solid #ddd;\">~$828,941</td></tr><tr><td style=\"padding:6px; border-bottom:1px solid #ddd;\">20 años</td><td style=\"padding:6px; border-bottom:1px solid #ddd;\">$480,000</td><td style=\"padding:6px; border-bottom:1px solid #ddd;\">~$72,000</td><td style=\"padding:6px; border-bottom:1px solid #ddd;\"><strong class=\"o\">~$1,518,738</strong></td></tr><tr><td style=\"padding:6px;\">25 años</td><td style=\"padding:6px;\">$600,000</td><td style=\"padding:6px;\">~$105,000</td><td style=\"padding:6px;\"><strong class=\"o\">~$2,653,667</strong></td></tr></table><span class=\"g\">Por cada peso que pagas en cargos, tu patrimonio crece muchas veces más.</span> A 20 años, pagas ~$72,000 en costos totales — y construyes más de $1.5 millones de pesos. Eso no es un gasto. <span class=\"g\">Es la inversión más rentable que harás.</span><br><br><em>*Estimación ilustrativa del costo total, usando la tasa oficial aplicada a tu saldo promedio a lo largo del plazo. **Proyección con rendimiento estimado del 10% anual (S&amp;P 500), consistente con nuestra proyección oficial. Los resultados reales dependen de tu Alternativa de Inversión y las condiciones del mercado — confirma tu cálculo exacto con tu asesor.</em></p>", "cat": "Costos y Transparencia — Todo claro, sin sorpresas", "snippet": "Cero costos ocultos — aquí está todo, con transparencia total. Tu plan tiene tres cargos mientras esté vigente..."}, {"q": "¿Hay algún costo por abrir mi plan?", "a": "<p style=\"margin:0;\"><strong>No hay un costo de apertura como tal.</strong> Lo que sí existe son los <strong>cargos normales de operación</strong> que ya viste (administrativo, gestión de inversión, y el cargo fijo que empieza hasta el mes 19) — <span class=\"g\">nada que se cobre solo por firmar o empezar.</span></p>", "cat": "Costos y Transparencia — Todo claro, sin sorpresas", "snippet": "No hay un costo de apertura como tal. Lo que sí existe son los cargos normales de operación que ya viste (admi..."}, {"q": "¿En qué casos se puede cancelar mi póliza automáticamente?", "a": "<p style=\"margin:0;\">Tu plan se cancela automáticamente en tres casos:<br><br>a) Si <strong>no cumples con el pago de tus aportaciones iniciales</strong> (los primeros 18 meses), y no te pones al corriente dentro de los 60 días de gracia.<br>b) Si haces un <strong>retiro total</strong> de tu saldo.<br>c) Si tu <strong>saldo total cae por debajo del 75%</strong> de tus aportaciones iniciales, una vez pasado el plazo inicial.<br><br><span class=\"g\">La buena noticia: los tres casos son totalmente evitables con constancia en tus aportaciones</span> — y para eso existen herramientas como tu Periodo de Descanso, diseñadas justo para que nunca llegues a este punto.</p>", "cat": "Costos y Transparencia — Todo claro, sin sorpresas", "snippet": "Tu plan se cancela automáticamente en tres casos: a) Si no cumples con el pago de tus aportaciones iniciales (..."}, {"q": "¿Cómo empiezo? ¿Qué necesito para contratar?", "a": "<p style=\"margin:0;\"><span class=\"g\">Empezar es más simple de lo que crees.</span><br><br>En tu <strong>primera cita</strong> (30 minutos), platicamos tu situación, definimos tu meta de retiro, y te mostramos exactamente qué plan te conviene y cuánto podrías construir.<br><br>Si decides seguir adelante, solo necesitas:<br><br>a) Tu <strong>identificación oficial vigente</strong>.<br>b) Definir tu <strong>aportación</strong> y <strong>plazo</strong>.<br>c) Elegir tu <strong>forma de pago</strong> (tarjeta, cuenta de cheques, o transferencia).<br><br><span class=\"g\">Nada complicado — solo la decisión de empezar hoy.</span></p>", "cat": "Cómo empezar", "snippet": "Empezar es más simple de lo que crees. En tu primera cita (30 minutos), platicamos tu situación, definimos tu..."}, {"q": "¿Cuánto tiempo toma activar mi plan?", "a": "<p style=\"margin:0;\">Una vez que decides seguir adelante, tu plan se activa rápido — normalmente en pocos días hábiles después de tu firma y tu primera aportación. <span class=\"g\">Entre más pronto empieces, antes empieza a trabajar tu dinero para ti.</span></p>", "cat": "Cómo empezar", "snippet": "Una vez que decides seguir adelante, tu plan se activa rápido — normalmente en pocos días hábiles después de t..."}, {"q": "¿Con quién hablo si tengo dudas antes de decidir?", "a": "<p style=\"margin:0;\">Con nosotros, directamente.<br><br><span class=\"g\">MAXX te acompaña en cada paso</span> — antes, durante y después de contratar tu plan.<br><br>No estás solo tomando esta decisión: <strong>agenda tu cita</strong> y/o solicita nuestro apoyo a través de <strong>contacto@maxx.mx</strong> y/o por medio del <strong>\"Chat\"</strong>, y resolvemos juntos cualquier duda que tengas, sin presión y a tu ritmo.</p>", "cat": "Cómo empezar", "snippet": "Con nosotros, directamente. MAXX te acompaña en cada paso — antes, durante y después de contratar tu plan. No..."}, {"q": "¿Qué es la Calificación Financiera Personal y para qué sirve?", "a": "<p style=\"margin:0;\">Es una <strong>herramienta gratuita e interactiva</strong> que te ayuda a ver, en minutos, <span class=\"g\">qué tan preparado estás para tu retiro</span> — con base en tu edad, tus ingresos, y tus metas.<br><br>Al terminarla, obtienes un <strong>diagnóstico personalizado</strong>: qué tan lejos o cerca estás de la <em>suficiencia de fondos para el retiro</em> y el <em>nivel de libertad económica</em> que quieres, así como qué necesitarías ahorrar para lograrlo.<br><br><strong>No es un examen que puedas reprobar</strong> — es una <span class=\"g\">fotografía honesta de tu situación actual</span>, para que tomes decisiones informadas, no a ciegas.<br><br><em>Conocer tu punto de partida es el primer paso para cambiar tu destino.</em><br><br><a href=\"#calificacion\" style=\"color:#185FA5; font-weight:bold;\">Empieza tu Calificación Financiera aquí →</a></p>", "cat": "Sobre tu Calificación Financiera Personal", "snippet": "Es una herramienta gratuita e interactiva que te ayuda a ver, en minutos, qué tan preparado estás para tu reti..."}, {"q": "¿Por qué es importante llenarla antes de mi cita?", "a": "<p style=\"margin:0;\">Porque convierte tu cita en algo <span class=\"g\">mucho más valioso para ti</span>.<br><br>En lugar de una plática general, llegas con <strong>tu diagnóstico ya listo</strong> — y usamos ese tiempo para hablar específicamente de <strong>tu situación, tus números, y tu plan</strong>, no de generalidades.<br><br>Es la diferencia entre llegar a una consulta médica sin exámenes, o llegar ya con tus resultados en mano: <em>la conversación es más rápida, más precisa, y más útil para ti.</em><br><br><a href=\"#calificacion\" style=\"color:#185FA5; font-weight:bold;\">Empieza tu Calificación Financiera aquí →</a></p>", "cat": "Sobre tu Calificación Financiera Personal", "snippet": "Porque convierte tu cita en algo mucho más valioso para ti. En lugar de una plática general, llegas con tu dia..."}, {"q": "¿Cuánto tiempo toma llenarla?", "a": "<p style=\"margin:0;\">Entre <strong class=\"o\">5 y 10 minutos</strong>.<br><br>Son preguntas simples sobre ti: tu edad, tus ingresos, y qué te gustaría lograr para tu retiro.<br><br><strong>No necesitas tener papeles ni cifras exactas a la mano</strong> — con estimaciones honestas es suficiente para obtener un diagnóstico útil.<br><br><em>¡Compruébalo tú mismo — es más fácil de lo que crees!</em><br><br><a href=\"#calificacion\" style=\"color:#185FA5; font-weight:bold;\">Empieza tu Calificación Financiera aquí →</a></p>", "cat": "Sobre tu Calificación Financiera Personal", "snippet": "Entre 5 y 10 minutos. Son preguntas simples sobre ti: tu edad, tus ingresos, y qué te gustaría lograr para tu..."}, {"q": "No puedo/no quiero llenar el cuestionario completo — ¿hay otra forma de obtener mi calificación?", "a": "<p style=\"margin:0;\">Claro que sí. Algunos prefieren que les ayudemos a hacerlo — y eso está bien.<br><br>Puedes dejarnos tus datos básicos en un formulario mucho más simple, y <strong>nosotros nos encargamos del resto</strong>: te contactamos directamente para hacer tu diagnóstico juntos, sin que tengas que llenar nada más por tu cuenta.<br><br><strong>Tú eliges el camino que mejor se acomode a ti</strong> — el importante es que des el primer paso.<br><br><a href=\"#calificacion-formulario\" style=\"color:#185FA5; font-weight:bold;\">Déjanos tus datos aquí →</a></p>", "cat": "Sobre tu Calificación Financiera Personal", "snippet": "Claro que sí. Algunos prefieren que les ayudemos a hacerlo — y eso está bien. Puedes dejarnos tus datos básico..."}, {"q": "Si prefiero que MAXX me contacte directamente, ¿qué datos necesito dar?", "a": "<p style=\"margin:0;\">Solo lo básico para poder ubicarte y platicar contigo:<br><br>a) Tu <strong>nombre</strong>.<br>b) Tu <strong>edad</strong>.<br>c) Un <strong>teléfono o correo</strong> de contacto.<br>d) Tu <strong>aportación mensual posible</strong> — para llegar con un panorama ya orientado a tu realidad, y no partir de cero.<br><br>En menos de un minuto dejas tus datos, y <strong>a la brevedad nos comunicaremos contigo</strong>.</p>", "cat": "Sobre tu Calificación Financiera Personal", "snippet": "Solo lo básico para poder ubicarte y platicar contigo: a) Tu nombre. b) Tu edad. c) Un teléfono o correo de co..."}, {"q": "¿Qué pasa con mis datos si los dejo para que me contacten?", "a": "<p style=\"margin:0;\">Tus datos se usan <strong>únicamente para contactarte</strong> y ayudarte con tu diagnóstico — nada más.<br><br>No los compartimos con terceros, ni los usamos para nada distinto a acompañarte en este proceso.<br><br><strong>Tu información está segura, y tú tienes el control</strong>: en cualquier momento puedes pedirnos que dejemos de contactarte.<br><br><a href=\"#aviso\" style=\"color:#185FA5; font-weight:bold;\">Consulta nuestro Aviso de Privacidad →</a></p>", "cat": "Sobre tu Calificación Financiera Personal", "snippet": "Tus datos se usan únicamente para contactarte y ayudarte con tu diagnóstico — nada más. No los compartimos con..."}, {"q": "¿Puedo mejorar mi calificación? ¿Cómo?", "a": "<p style=\"margin:0;\">Sí, siempre. <strong>Tu calificación de hoy no es tu destino — solo es tu punto de partida</strong>.<br><br>Puedes mejorarla de varias formas:<br><br>a) aumentando tu aportación mensual,<br>b) ajustando tu plazo de retiro, o<br>c) empezando antes en lugar de después — <strong>el tiempo es tu mejor aliado.</strong><br><br>Puedes volver a llenar tu Calificación las veces que quieras, para ver cómo cambian tus resultados con distintos escenarios — y encontrar el que mejor se ajuste a TI.<br><br><a href=\"#calificacion\" style=\"color:#185FA5; font-weight:bold;\">Vuelve a intentarlo aquí →</a></p>", "cat": "Sobre tu Calificación Financiera Personal", "snippet": "Sí, siempre. Tu calificación de hoy no es tu destino — solo es tu punto de partida. Puedes mejorarla de varias..."}, {"q": "¿Mi calificación es un compromiso de contratar algo?", "a": "<p style=\"margin:0;\">No, para nada. Tu Calificación Financiera es <strong>100% informativa</strong> — no firmas nada, no te comprometes a nada, y no hay ninguna letra chiquita.<br><br><strong>El único compromiso que estableces es contigo mismo</strong> — con conocerte mejor, con dejar de adivinar, empezar a saber y sobretodo: <strong>tener un punto de partida para ya empezar a construir tu futuro.</strong><br><br><a href=\"#calificacion\" style=\"color:#185FA5; font-weight:bold;\">Conoce tu Calificación aquí →</a></p>", "cat": "Sobre tu Calificación Financiera Personal", "snippet": "No, para nada. Tu Calificación Financiera es 100% informativa — no firmas nada, no te comprometes a nada, y no..."}, {"q": "¿En qué se basan las proyecciones de mi Calificación Financiera, si no están garantizadas?", "a": "<p style=\"margin:0;\">Se basan en el <strong>rendimiento histórico real del S&amp;P 500</strong> — uno de los índices más estudiados y consistentes del mundo — usando ventanas de tiempo largas (10, 15, 20, 25 y 30 años) para suavizar los altibajos normales del mercado.<br><br><strong>No es una promesa, es una proyección seria</strong> — construida con datos reales, no con optimismo inventado.</p>", "cat": "Sobre tu Calificación Financiera Personal", "snippet": "Se basan en el rendimiento histórico real del S&P 500 — uno de los índices más estudiados y consistentes del m..."}, {"q": "¿Cuánto voy a recibir de pensión cuando me retire?", "a": "<p style=\"margin:0;\">Depende de tu régimen, pero el dato real te va a sorprender: bajo la <strong>Ley 97</strong> (la que aplica a la mayoría hoy), estudios de la <strong>OCDE y Banxico</strong> muestran que tu pensión podría ser de solo <strong class=\"o\">26% a 30% de tu último salario</strong>.<br><br>Para comparar: la OCDE considera que un retiro adecuado necesita <strong class=\"o\">alrededor del 70%</strong> de tu último salario.<br><br>La brecha entre lo que vas a recibir y lo que realmente necesitas es real — y es tu responsabilidad el llenarla.<br><br>Simplemente, <strong>depender de una pensión, para tener un retiro digno, ya no es suficiente.</strong><br><br><span style=\"padding-left:20px; display:block; font-size:13.5px; color:#5F5E5A;\"><em>Vale la pena saberlo: desde la reforma de 2020, la aportación obligatoria a tu AFORE está subiendo de forma gradual — de ~6.5% hasta ~15% de tu salario para el año 2030. Con el tiempo, esto podría mejorar tu tasa de reemplazo hacia un 45%-55%. Aun así, seguiría estando por debajo del 70% que se considera un retiro adecuado — la brecha se reduce, pero no desaparece.</em></span><br><br><em style=\"font-size:12.5px; color:#8A8778;\">Fuente: OCDE — Pensions at a Glance; Banxico; reforma de pensiones publicada en el DOF el 16 de diciembre de 2020.</em></p>", "cat": "Sobre tu pensión del IMSS/Seguro Social", "snippet": "Depende de tu régimen, pero el dato real te va a sorprender: bajo la Ley 97 (la que aplica a la mayoría hoy),..."}, {"q": "¿Por qué no me va a alcanzar solo con mi pensión?", "a": "<p style=\"margin:0;\">Porque el sistema <strong>ya no está diseñado para reemplazar tu salario</strong> — está diseñado solo para complementarlo.<br><br>A esto se suman dos factores que reducen aún más lo que realmente recibes:<br><br>a) La <strong>inflación</strong> va desgastando el poder de compra de tu pensión con los años.<br>b) Muchas personas <strong>no completan las semanas mínimas cotizadas</strong> que exige la ley, lo que reduce o incluso elimina su derecho a la Pensión Garantizada.<br><br>No es que el sistema esté \"mal\" — es que fue diseñado para otra época.<br><br><strong>Hoy, construir tu propio respaldo ya no es opcional: es indispensable.</strong><br><br><em style=\"font-size:12.5px; color:#8A8778;\">Fuente: reforma de pensiones, DOF 16 de diciembre de 2020.</em></p>", "cat": "Sobre tu pensión del IMSS/Seguro Social", "snippet": "Porque el sistema ya no está diseñado para reemplazar tu salario — está diseñado solo para complementarlo. A e..."}, {"q": "¿Cómo se actualiza mi pensión con el tiempo?", "a": "<p style=\"margin:0;\">Tu pensión se actualiza anualmente conforme a la <strong>inflación (medida por el INPC)</strong> — es decir, sube cada año para tratar de mantener su poder de compra.<br><br>El problema es que esta actualización <strong>solo compensa la inflación oficial</strong>, no necesariamente el aumento real en tu costo de vida (salud, vivienda, alimentos suelen subir más rápido que el promedio general).<br><br><strong>Que se \"actualice\" no significa que te alcance más</strong> — solo significa que pierde menos valor de lo que perdería sin ese ajuste.<br><br><em style=\"font-size:12.5px; color:#8A8778;\">Fuente: Art. 75, Ley del Seguro Social.</em></p>", "cat": "Sobre tu pensión del IMSS/Seguro Social", "snippet": "Tu pensión se actualiza anualmente conforme a la inflación (medida por el INPC) — es decir, sube cada año para..."}, {"q": "¿Es lo mismo el INPC que la inflación real que yo vivo?", "a": "<p style=\"margin:0;\">No, casi nunca. El INPC es un promedio nacional, calculado con una canasta genérica de productos y servicios — pero <strong>tu inflación personal depende de en qué gastas tú</strong>.<br><br>Si gastas más en salud, colegiaturas o vivienda (categorías que suelen subir más rápido que el promedio), <strong>tu inflación real puede ser más alta que el INPC oficial</strong>.<br><br>Por eso, cuando tu pensión se actualiza \"según la inflación\", en la práctica <strong>puede seguir perdiendo poder de compra frente a tu realidad específica</strong>.<br><br><em style=\"font-size:12.5px; color:#8A8778;\">Fuente: INEGI — Metodología del Índice Nacional de Precios al Consumidor (INPC).</em></p>", "cat": "Sobre tu pensión del IMSS/Seguro Social", "snippet": "No, casi nunca. El INPC es un promedio nacional, calculado con una canasta genérica de productos y servicios —..."}, {"q": "¿Desde cuándo cambió el sistema de pensiones en México?", "a": "<p style=\"margin:0;\">En <strong class=\"o\">julio de 1997</strong>, cuando México cambió de un sistema de <strong>beneficio definido</strong> (Ley 73) a uno de <strong>contribución definida</strong> (Ley 97).<br><br>Antes de ese cambio, tu pensión se calculaba con una <strong>fórmula fija</strong> basada en tu salario y tus semanas cotizadas — el gobierno garantizaba el resultado.<br><br>Después del cambio, tu pensión depende del <strong>saldo que acumules en tu cuenta individual (AFORE)</strong> — ya no hay una fórmula garantizada de reemplazo salarial.<br><br><strong>El resultado ahora depende, en gran parte, de ti.</strong><br><br><em style=\"font-size:12.5px; color:#8A8778;\">Fuente: Ley del Seguro Social, reforma vigente a partir del 1 de julio de 1997.</em></p>", "cat": "Sobre tu pensión del IMSS/Seguro Social", "snippet": "En julio de 1997, cuando México cambió de un sistema de beneficio definido (Ley 73) a uno de contribución defi..."}, {"q": "¿Mi pensión del IMSS y mi plan con MAXX son lo mismo o algo distinto?", "a": "<p style=\"margin:0;\"><strong>Son completamente distintos</strong> — y esa diferencia es justo lo que te da poder de decisión.<br><br>Tu pensión del IMSS/AFORE es <strong>obligatoria</strong>. No la elegiste, no la diseñaste, y <strong>no la controlas</strong>: cuánto se aporta, cómo se invierte, cuándo puedes tocarla — todo lo decide la ley, no tú.<br><br>Tu Plan con MAXX es exactamente lo opuesto: <strong>tú decides todo</strong>. Cuánto aportas, por cuánto tiempo, y en qué crece tu dinero.<br><br><strong>No compiten — se complementan.</strong> Tu AFORE es el piso que la ley te obliga a tener. <strong>Tu Plan MAXX es el patrimonio que TÚ eliges construir arriba de ese piso.</strong><br><br><span class=\"g\">La diferencia entre un retiro que te tocó, y un retiro que tú diseñaste.</span></p>", "cat": "Sobre tu pensión del IMSS/Seguro Social", "snippet": "Son completamente distintos — y esa diferencia es justo lo que te da poder de decisión. Tu pensión del IMSS/AF..."}, {"q": "¿Cuál es el mínimo de semanas que debo cotizar para derecho a pensión? ¿Qué pasa con mi pensión si no las podré completar y qué puedo hacer para obtener una pensión?", "a": "<p style=\"margin:0;\">El mínimo actual para tener derecho a la <strong>Pensión Garantizada</strong> son <strong class=\"o\">875 semanas cotizadas</strong> (2026) — esa cifra sube gradualmente hasta <strong class=\"o\">1,000 semanas en 2031</strong>.<br><br>Si no las completas, <strong>no pierdes tu dinero</strong> — el saldo de tu AFORE sigue siendo tuyo.<br><br>Pero <strong>sí pierdes el derecho a la Pensión Garantizada</strong> que respalda un mínimo del gobierno.<br><br><strong>La buena noticia: existen mecanismos legales para seguir sumando semanas</strong>, como Modalidad 40 y Modalidad 10.<br><br><em>Conoce cómo funcionan — y qué hacer si dejaste de cotizar hace tiempo — en la siguiente pregunta.</em><br><br><strong>La mejor estrategia para tu caso se revisa contigo, en tu cita.</strong><br><br><em style=\"font-size:12.5px; color:#8A8778;\">Fuente: Art. 170, Ley del Seguro Social (Pensión Garantizada).</em></p>", "cat": "Sobre tu pensión del IMSS/Seguro Social", "snippet": "El mínimo actual para tener derecho a la Pensión Garantizada son 875 semanas cotizadas (2026) — esa cifra sube..."}, {"q": "¿Cómo funciona Modalidad 40 (y Modalidad 10) para sumar semanas si dejé de cotizar?", "a": "<p style=\"margin:0;\"><strong>Modalidad 40</strong> es tu mecanismo del IMSS para <strong>seguir cotizando por tu cuenta</strong>, aunque ya no tengas un patrón — sumando semanas y, sobre todo, mejorando el salario que se usa para calcular tu pensión.<br><br>Para poder inscribirte directo, necesitas:<br><br><span style=\"padding-left:20px; display:block;\">a) Haber cotizado <strong>al menos 52 semanas</strong> en los 5 años previos a tu baja.</span><span style=\"padding-left:20px; display:block;\">b) Solicitarlo dentro de los <strong>5 años siguientes</strong> a tu fecha de baja — pasado ese plazo, <strong>el derecho se pierde</strong>.</span><span style=\"padding-left:20px; display:block;\">c) Elegir un salario de cotización igual o mayor al que tenías al momento de tu baja (con un tope de 25 UMAs).</span><br><br><strong>¿Ya pasaron más de 5 años desde que dejaste de cotizar? Respira — no perdiste la opción por completo.</strong> Solo necesitas reabrir la puerta:<br><br><span style=\"padding-left:20px; display:block;\">a) <strong>Reingresas al régimen obligatorio</strong> — con un empleo formal, o dándote de alta en <strong>Modalidad 10</strong> (como trabajador independiente) — por al menos <strong>52 semanas</strong>.</span><span style=\"padding-left:20px; display:block;\">b) Al cumplir ese año, <strong>te das de baja otra vez</strong>.</span><span style=\"padding-left:20px; display:block;\">c) Eso <strong>reabre tu plazo de 5 años</strong> para poder inscribirte en Modalidad 40.</span><br><br>Este esquema es especialmente poderoso si cotizaste antes de 1997 (<strong>Ley 73</strong>), porque tu pensión se calcula con el <strong>promedio de tus últimas 250 semanas</strong> — cotizar con un salario alto justo antes de tu retiro puede <strong>multiplicar tu pensión final</strong>.<br><br><strong>Tu caso es único.</strong> Tu historial, tus semanas, tu edad, tu régimen — todo eso cambia por completo cuál es tu mejor estrategia.<br><br><strong>Lo resolvemos juntos, contigo, en tu cita.</strong><br><br><em style=\"font-size:12.5px; color:#8A8778;\">Fuente: Arts. 218-219, Ley del Seguro Social (Modalidad 40).</em></p>", "cat": "Sobre tu pensión del IMSS/Seguro Social", "snippet": "Modalidad 40 es tu mecanismo del IMSS para seguir cotizando por tu cuenta, aunque ya no tengas un patrón — sum..."}, {"q": "¿Los rendimientos que me muestran están garantizados?", "a": "<p style=\"margin:0;\">Los rendimientos que ves son proyecciones basadas en datos históricos reales — no representan promesas, ni garantías.<br><br><strong>Los portafolios se componen de índices/tasas que suben y bajan.</strong><br><br><strong>Nadie puede prometerte un número exacto para el futuro</strong> — ni MAXX, ni nadie más.<br><br><strong>MAXX te ofrece transparencia total</strong>: te mostramos de dónde salen esos números, para que decidas con información real, no con ilusiones.<br><br><strong>Tú mismo puedes ajustar las tasas de interés e inflación al momento de obtener tu Calificación Financiera</strong>, de forma que la proyección sea tuya, y de nadie más.</p>", "cat": "Portafolios de Inversión y sus Rendimientos", "snippet": "Los rendimientos que ves son proyecciones basadas en datos históricos reales — no representan promesas, ni gar..."}, {"q": "¿En qué se basan esas proyecciones si no están garantizadas?", "a": "<p style=\"margin:0;\">Se basan en el <strong>rendimiento histórico real del S&amp;P 500</strong> — uno de los índices más estudiados y consistentes del mundo — usando ventanas de tiempo largas (10, 15, 20, 25 y 30 años) para suavizar los altibajos normales del mercado.<br><br><strong>No es una promesa, es una proyección seria</strong> — construida con datos reales, no con optimismo inventado.</p>", "cat": "Portafolios de Inversión y sus Rendimientos", "snippet": "Se basan en el rendimiento histórico real del S&P 500 — uno de los índices más estudiados y consistentes del m..."}, {"q": "Si quiero algo 100% garantizado, ¿existe esa opción?", "a": "<p style=\"margin:0;\">Sí, existe. CETES es un ejemplo: un instrumento de tasa fija, pero <strong>fija solo por el periodo que contratas</strong> (28, 91, 182 o 364 días) — al vencer, la tasa se renueva según las condiciones del mercado en ese momento. <strong>No es la misma tasa de un periodo a otro.</strong><br><br>Para que lo veas en números reales: en los últimos 10 años, <strong class=\"o\">CETES ha rendido en un rango de ~7% a ~11% anual</strong> (en pesos), mientras que el <strong class=\"o\">S&amp;P 500 ha rendido ~12% a 14% anual</strong> (en dólares, con dividendos reinvertidos).<br><br>Es importante ser honestos contigo: <strong>a menor riesgo, generalmente menor rendimiento potencial</strong> — es la relación natural de cualquier inversión, en cualquier parte del mundo.<br><br><strong>Tú decides qué balance quieres</strong> entre seguridad y crecimiento. De hecho, puedes <strong>invertir en varias Alternativas al mismo tiempo</strong>, respetando el mínimo de inversión de cada una — mezclando estabilidad y crecimiento a tu propio gusto.<br><br><a href=\"#section09\" style=\"color:#185FA5; font-weight:bold;\">Conoce tus opciones aquí →</a><br><br><em style=\"font-size:12.5px; color:#8A8778;\">Fuente: Banxico (CETES); S&amp;P Dow Jones Indices (S&amp;P 500).</em></p>", "cat": "Portafolios de Inversión y sus Rendimientos", "snippet": "Sí, existe. CETES es un ejemplo: un instrumento de tasa fija, pero fija solo por el periodo que contratas (28,..."}, {"q": "¿Qué tan confiable es usar el rendimiento histórico como referencia?", "a": "<p style=\"margin:0;\"><strong>Es la mejor referencia disponible — pero no es una bola de cristal.</strong><br><br>El pasado <strong>no garantiza el futuro</strong>, eso es cierto. Pero usar décadas de datos reales, en vez de una corazonada u optimismo sin fundamento, es la forma más responsable de estimar lo que razonablemente podrías esperar.<br><br>Por eso MAXX usa <strong>ventanas de tiempo largas</strong> (10, 15, 20, 25, hasta 30 años) — para suavizar los años buenos y los malos, y darte una proyección realista, no una fantasía.<br><br><span class=\"g\">Confiar en datos reales siempre será mejor que confiar en promesas vacías.</span></p>", "cat": "Portafolios de Inversión y sus Rendimientos", "snippet": "Es la mejor referencia disponible — pero no es una bola de cristal. El pasado no garantiza el futuro, eso es c..."}, {"q": "¿Qué pasa si el mercado tiene un mal año?", "a": "<p style=\"margin:0;\"><strong>Nada dramático, si tu plan está bien diseñado para el largo plazo.</strong><br><br>Los mercados tienen años buenos y años malos — es normal, es parte de cómo funcionan. Lo que importa no es un año aislado, sino <strong>la tendencia de muchos años juntos</strong>.<br><br>Por eso tu plan está pensado para <strong>plazos largos</strong> (10 a 25 años): un mal año se diluye dentro de una trayectoria mucho más amplia, mientras tu dinero sigue trabajando para ti.<br><br><span class=\"g\">Vender por pánico en un mal momento es de las decisiones más caras que puedes tomar</span> — quedarte con la vista puesta en tu meta, no en el ruido del día a día, es lo que realmente construye patrimonio.</p>", "cat": "Portafolios de Inversión y sus Rendimientos", "snippet": "Nada dramático, si tu plan está bien diseñado para el largo plazo. Los mercados tienen años buenos y años malo..."}, {"q": "¿Puedo cambiar de portafolio(s) si me es necesario?", "a": "<p style=\"margin:0;\">Sí, y con mucha libertad.<br><br>Puedes asignar tu inversión a cualquiera de las <strong>19 Alternativas de Inversión</strong> disponibles, o mezclarlas como tú prefieras — respetando un mínimo de <strong class=\"o\">$10,000 pesos</strong> por Alternativa.<br><br>No es una decisión de una sola vez: <strong>mes a mes puedes redistribuir</strong> la composición de tu inversión conforme cambien tus necesidades o tu visión del mercado.<br><br><strong>Tú tienes el control, siempre.</strong><br><br><a href=\"#section09\" style=\"color:#185FA5; font-weight:bold;\">Conoce las 19 alternativas disponibles →</a></p>", "cat": "Portafolios de Inversión y sus Rendimientos", "snippet": "Sí, y con mucha libertad. Puedes asignar tu inversión a cualquiera de las 19 Alternativas de Inversión disponi..."}, {"q": "¿Cómo agendo mi cita?", "a": "<p style=\"margin:0;\">Más fácil de lo que crees.<br><br>Puedes agendarla directamente en línea, eligiendo el día y la hora que mejor te acomode — sin llamadas, sin esperas.<br><br><a href=\"#cita-desde-faqs\" style=\"color:#185FA5; font-weight:bold;\">Agenda TU Cita aquí →</a><br><br><strong>Tú eliges cuándo. Nosotros nos ajustamos a ti.</strong></p>", "cat": "Sobre tu cita con MAXX", "snippet": "Más fácil de lo que crees. Puedes agendarla directamente en línea, eligiendo el día y la hora que mejor te aco..."}, {"q": "¿La cita tiene algún costo?", "a": "<p style=\"margin:0;\">No, cero costo. Tu primera cita con MAXX es <strong class=\"o\">100% gratuita</strong> — sin letra chiquita, sin sorpresas.<br><br>Es una oportunidad para que conozcas tu situación real y las opciones que tienes, <strong>sin ningún compromiso de tu parte</strong>.<br><br><a href=\"#cita-desde-faqs\" style=\"color:#185FA5; font-weight:bold;\">Agenda TU Cita aquí →</a></p>", "cat": "Sobre tu cita con MAXX", "snippet": "No, cero costo. Tu primera cita con MAXX es 100% gratuita — sin letra chiquita, sin sorpresas. Es una oportuni..."}, {"q": "¿Cuánto dura la cita?", "a": "<p style=\"margin:0;\">Alrededor de <strong class=\"o\">30 minutos</strong>.<br><br>Es tiempo suficiente para conocer tu situación, resolver tus dudas, y mostrarte con claridad qué opciones tienes — sin prisas, pero sin quitarte más tiempo del necesario.<br><br>Si llegas con tu <strong>Calificación Financiera</strong> ya lista, aprovechamos ese tiempo aún mejor: hablamos directo de TU situación, TUS números, y TU plan.<br><br><a href=\"#calificacion\" style=\"color:#185FA5; font-weight:bold;\">Prepárala antes de tu cita aquí →</a></p>", "cat": "Sobre tu cita con MAXX", "snippet": "Alrededor de 30 minutos. Es tiempo suficiente para conocer tu situación, resolver tus dudas, y mostrarte con c..."}, {"q": "¿Es en persona, por video, o telefónica?", "a": "<p style=\"margin:0;\"><strong>Tú eliges el formato que más te acomode.</strong><br><br>Puede ser por <strong>videollamada (Google Meet)</strong> o <strong>en persona</strong>, según lo que prefieras y lo que mejor se ajuste a tu agenda.<br><br>Al agendar, tu cita queda configurada automáticamente por videollamada — si prefieres que sea en persona, <strong>solo dínoslo al confirmar tu horario</strong>, y lo ajustamos contigo.</p>", "cat": "Sobre tu cita con MAXX", "snippet": "Tú eliges el formato que más te acomode. Puede ser por videollamada (Google Meet) o en persona, según lo que p..."}, {"q": "¿Necesito llevar algo preparado a mi cita?", "a": "<p style=\"margin:0;\">No es obligatorio, pero <strong>sí te conviene</strong> — entre más preparado llegues, más útil será tu cita.<br><br>Lo ideal es que llegues con tu <strong>Calificación Financiera</strong> ya lista: así hablamos directo de tu situación real, tus números, y tu plan — no de generalidades.<br><br>Si no la has llenado, no pasa nada — <strong>la resolvemos juntos en la cita</strong>, o de ser necesario, después de ella.<br><br><a href=\"#calificacion\" style=\"color:#185FA5; font-weight:bold;\">Prepárala antes de tu cita aquí →</a></p>", "cat": "Sobre tu cita con MAXX", "snippet": "No es obligatorio, pero sí te conviene — entre más preparado llegues, más útil será tu cita. Lo ideal es que l..."}, {"q": "¿Hay algún compromiso de contratar por agendar una cita?", "a": "<p style=\"margin:0;\"><strong>No, absolutamente ninguno.</strong><br><br>Agendar tu cita <strong>no te obliga a nada</strong> — es una conversación, no una venta forzada.<br><br>El único objetivo es que salgas con <strong>más información y más claridad</strong> de la que tenías antes de entrar. Lo que decidas hacer después, <strong>siempre es tu decisión, a tu ritmo.</strong><br><br>Pero hay algo que sí vale la pena decirte con honestidad: <strong class=\"o\">el tiempo es tu enemigo número 1.</strong> Cada mes que pasa sin empezar, es un mes de rendimiento que ya no regresa — y una aportación mensual más grande para llegar a la misma meta.<br><br><span class=\"g\">No hay ningún compromiso en agendar. El único riesgo real es seguir esperando.</span><br><br><a href=\"#cita-desde-faqs\" style=\"color:#185FA5; font-weight:bold;\">Agenda TU Cita aquí →</a></p>", "cat": "Sobre tu cita con MAXX", "snippet": "No, absolutamente ninguno. Agendar tu cita no te obliga a nada — es una conversación, no una venta forzada. El..."}];

  var css = document.createElement('style');
  css.textContent = `
    #maxx-faq-search-btn {
      position: fixed; bottom: 24px; right: 24px; z-index: 9999;
      width: 56px; height: 56px; border-radius: 50%;
      background: #042C53; color: #FFF; border: none;
      font-size: 24px; cursor: pointer;
      box-shadow: 0 4px 14px rgba(0,0,0,0.25);
      display: flex; align-items: center; justify-content: center;
      font-family: 'Roboto', Arial, sans-serif;
    }
    #maxx-faq-search-panel {
      position: fixed; bottom: 90px; right: 24px; z-index: 9999;
      width: 360px; max-width: calc(100vw - 40px);
      background: #FFF; border-radius: 14px;
      box-shadow: 0 8px 30px rgba(0,0,0,0.25);
      display: none; flex-direction: column;
      max-height: 75vh; overflow: hidden;
      font-family: 'Roboto', Arial, sans-serif;
    }
    #maxx-faq-search-panel.open { display: flex; }
    #maxx-faq-search-header {
      background: #042C53; color: #FFF; padding: 14px 16px;
      font-weight: bold; font-size: 15px;
      display: flex; justify-content: space-between; align-items: center;
      flex-shrink: 0;
    }
    #maxx-faq-search-back {
      cursor: pointer; background: none; border: none; color: #FFF;
      font-size: 13px; font-weight: bold; display: none; align-items: center; gap: 4px;
      padding: 10px 16px 0 16px; flex-shrink: 0;
    }
    #maxx-faq-search-back.show { display: flex; }
    #maxx-faq-search-close { cursor: pointer; font-size: 18px; background: none; border: none; color: #FFF; }
    #maxx-faq-search-input {
      margin: 12px 14px; padding: 10px 14px;
      border: 2px solid #185FA5; border-radius: 20px;
      font-size: 14px; font-family: 'Roboto', Arial, sans-serif;
      outline: none; flex-shrink: 0;
    }
    #maxx-faq-search-results {
      overflow-y: auto; padding: 0 14px 14px 14px; flex: 1;
    }
    .maxx-faq-result {
      display: block; text-align: left; width: 100%;
      background: #F5F4F0; border: none; border-radius: 10px;
      padding: 10px 12px; margin-bottom: 8px; cursor: pointer;
    }
    .maxx-faq-result:hover { background: #E6F1FB; }
    .maxx-faq-result-q { color: #185FA5; font-weight: bold; font-size: 13.5px; margin: 0 0 4px 0; }
    .maxx-faq-result-cat { color: #639922; font-size: 11px; font-weight: bold; text-transform: uppercase; margin: 0 0 3px 0; }
    .maxx-faq-result-snippet { color: #555; font-size: 12px; margin: 0; line-height: 1.4; }
    .maxx-faq-result-leermas { color: #185FA5; font-weight: bold; white-space: nowrap; }
    .maxx-faq-no-results { color: #888; font-size: 13px; text-align: center; padding: 20px 10px; }
    .maxx-faq-answer-cat { color: #639922; font-size: 11px; font-weight: bold; text-transform: uppercase; margin: 0 0 6px 0; }
    .maxx-faq-answer-q { color: #042C53; font-size: 16px; font-weight: 900; margin: 0 0 12px 0; line-height: 1.3; }
    .maxx-faq-answer-body { color: #333; font-size: 14px; line-height: 1.55; }
    .maxx-faq-answer-body .g { color: #639922; font-weight: bold; }
    .maxx-faq-answer-body .o { color: #639922; }
    .maxx-faq-answer-body strong.o { color: #639922; }
  `;
  document.head.appendChild(css);

  var btn = document.createElement('button');
  btn.id = 'maxx-faq-search-btn';
  btn.innerHTML = '?';
  btn.title = 'Busca tu duda';
  document.body.appendChild(btn);

  var panel = document.createElement('div');
  panel.id = 'maxx-faq-search-panel';
  panel.innerHTML = `
    <div id="maxx-faq-search-header">
      <span id="maxx-faq-search-title">¿Cuál es tu duda?</span>
      <button id="maxx-faq-search-close">✕</button>
    </div>
    <button id="maxx-faq-search-back">← Volver a resultados</button>
    <input id="maxx-faq-search-input" type="text" placeholder="Escribe tu pregunta..." />
    <div id="maxx-faq-search-results"></div>
  `;
  document.body.appendChild(panel);

  var input = document.getElementById('maxx-faq-search-input');
  var results = document.getElementById('maxx-faq-search-results');
  var closeBtn = document.getElementById('maxx-faq-search-close');
  var backBtn = document.getElementById('maxx-faq-search-back');
  var titleEl = document.getElementById('maxx-faq-search-title');

  function normalize(s) {
    return s.toLowerCase()
      .normalize('NFD').replace(/[\u0300-\u036f]/g, '')
      .replace(/[¿?¡!]/g, '');
  }

  function score(item, terms) {
    var text = normalize(item.q + ' ' + item.snippet + ' ' + item.cat);
    var s = 0;
    terms.forEach(function(t) {
      if (t.length < 2) return;
      if (text.indexOf(t) !== -1) s += 1;
      if (normalize(item.q).indexOf(t) !== -1) s += 2;
    });
    return s;
  }

  function showResultsView() {
    input.style.display = 'block';
    backBtn.classList.remove('show');
    titleEl.textContent = '¿Cuál es tu duda?';
    renderResults(input.value);
  }

  function showAnswerView(item) {
    input.style.display = 'none';
    backBtn.classList.add('show');
    titleEl.textContent = 'TU respuesta';
    results.innerHTML =
      '<div class="maxx-faq-answer-cat">' + item.cat + '</div>' +
      '<div class="maxx-faq-answer-q">' + item.q + '</div>' +
      '<div class="maxx-faq-answer-body">' + item.a + '</div>';
  }

  function renderResults(query) {
    results.innerHTML = '';
    if (!query.trim()) {
      results.innerHTML = '<div class="maxx-faq-no-results">Escribe una palabra clave (ej. "bono", "retiro", "impuestos")...</div>';
      return;
    }
    var terms = normalize(query).split(/\s+/).filter(Boolean);
    var scored = DATA.map(function(item) {
      return { item: item, s: score(item, terms) };
    }).filter(function(x) { return x.s > 0; });
    scored.sort(function(a, b) { return b.s - a.s; });
    scored = scored.slice(0, 6);

    if (scored.length === 0) {
      results.innerHTML = '<div class="maxx-faq-no-results">No encontramos coincidencias. Prueba con otra palabra, o agenda tu cita para resolverlo directo.</div>';
      return;
    }

    scored.forEach(function(x) {
      var item = x.item;
      var el = document.createElement('button');
      el.type = 'button';
      el.className = 'maxx-faq-result';
      el.innerHTML = '<div class="maxx-faq-result-cat">' + item.cat + '</div>' +
                      '<div class="maxx-faq-result-q">' + item.q + '</div>' +
                      '<div class="maxx-faq-result-snippet">' + item.snippet + ' <span class="maxx-faq-result-leermas">Leer más →</span></div>';
      el.addEventListener('click', function() {
        showAnswerView(item);
      });
      results.appendChild(el);
    });
  }

  btn.addEventListener('click', function() {
    panel.classList.toggle('open');
    if (panel.classList.contains('open')) {
      showResultsView();
      input.focus();
    }
  });
  closeBtn.addEventListener('click', function() {
    panel.classList.remove('open');
  });
  backBtn.addEventListener('click', function() {
    showResultsView();
  });
  input.addEventListener('input', function() {
    renderResults(input.value);
  });
})();
